mapper.select:
select m.id as material_id, m.name as material_name, mt.name as type_name, m.spec, m.price, m.warn_threshold, coalesce(sum(wm.inventory), 0) as total_inventory, case when m.warn_threshold is not null and coalesce(sum(wm.inventory), 0) < m.warn_threshold then 1 else 0 end as low_stock from material m left join material_type mt on m.type_id = mt.id left join warehouse_material wm on wm.material_id = m.id left join warehouse_record wr on wm.warehouse_record_id = wr.id and wr.status = 1 and wr.del_flag = 0
and wr.warehouse_id = #{warehouseId}
where m.del_flag = 0
and m.name like concat('%', #{materialName}, '%')
and m.type_id = #{typeId}
group by m.id, m.name, mt.name, m.spec, m.price, m.warn_threshold order by m.id
